function OpenList_Loaded(){document.body.classList.add("loaded")}function hexToRgb(o){return`${parseInt(o.slice(1,3),16)} ${parseInt(o.slice(3,5),16)} ${parseInt(o.slice(5,7),16)}`}window.addEventListener("load",OpenList_Loaded),document.documentElement.style.setProperty("--moe-color-theme",hexToRgb(window.OPENLIST_CONFIG?.main_color)),console.log("\n %c LJH OpenList %c v1.0 ","padding: 5px 0; border-radius: 3px 0 0 3px; color: #fff; background: #006d34; font-weight: bold;","padding: 5px 0; border-radius: 0 3px 3px 0; color: #fff; background: #008c4a; font-weight: bold;"),console.log("\n %c 适用于 OpenList Test ","padding: 5px 0; border-radius: 3px; color: #fff; background: linear-gradient(90deg, #006d34 0%, #008c4a 50%, #00a862 100%); font-weight: bold;"),console.log("\n %c Customized by LJH %c 基于 OpenList Moe ","padding: 5px 0; border-radius: 3px 0 0 3px; color: #fff; background: linear-gradient(to right, #006d34, #008c4a); font-weight: bold;","padding: 5px 0; border-radius: 0 3px 3px 0; color: #006d34; background: #e8f5e9; font-weight: bold;");
